<?php
$rows=db()->query("SELECT id,nama,username,email,no_hp,role,status,last_login_at,created_at FROM users ORDER BY FIELD(role,'admin','pengurus','warga'),nama LIMIT 300")->fetchAll();
?>
<div class="page-heading"><div><h1>Manajemen Akun</h1><p>Kelola status akun yang dapat mengakses SIPARTA.</p></div><span class="badge text-bg-info px-3 py-2">Admin memiliki akses penuh</span></div>
<section class="panel-card"><div class="data-toolbar"><span class="text-muted-2"><?= count($rows) ?> akun terdaftar</span><span class="text-muted-2 small ms-auto">Akun Pengurus dibuat melalui kode akses. Akun Warga dibuat melalui pendaftaran mandiri.</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Pengguna</th><th>Email / Username</th><th>Role</th><th>Status</th><th>Login terakhir</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><strong><?= e($a['nama']) ?></strong><small class="d-block text-muted-2">Terdaftar <?= e(format_date($a['created_at'])) ?></small></td><td><?= e($a['email']) ?><small class="d-block text-muted-2"><?= e($a['username']?:'Tanpa username') ?></small></td><td><?= status_badge($a['role']) ?></td><td><?= status_badge($a['status']) ?></td><td><?= e($a['last_login_at']?format_datetime($a['last_login_at']):'Belum pernah') ?></td><td><?php if($a['role']!=='admin'): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_account"><input type="hidden" name="return_page" value="manajemen-akun"><input type="hidden" name="id" value="<?= $a['id'] ?>"><button class="btn btn-sm <?= $a['status']==='aktif'?'btn-outline-danger':'btn-outline-success' ?>" data-confirm="<?= $a['status']==='aktif'?'Nonaktifkan':'Aktifkan' ?> akun <?= e($a['nama']) ?>?"><?= $a['status']==='aktif'?'Nonaktifkan':'Aktifkan' ?></button></form><?php else: ?><span class="small text-muted-2">Akun sistem</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
